// 20-tap direct-form FIR, 8-bit samples, PIPELINED: products registered in
// stage 1, summed in stage 2 -> shorter register-to-register path, higher Fmax.
// Functionally identical to the reference up to a fixed extra latency.
module firr20_v6 (
    input  wire        clk,
    input  wire        rst_n,
    input  wire [7:0]  x,
    output reg  [15:0] y
);
    reg  [7:0]  xs [0:19];
    reg  [15:0] p  [0:19];
    integer     i;
    always @(posedge clk) begin
        if (!rst_n) begin
            for (i = 0; i < 20; i = i + 1) begin xs[i] <= 8'd0; p[i] <= 16'd0; end
            y <= 16'd0;
        end else begin
            xs[0] <= x;
            for (i = 1; i < 20; i = i + 1) xs[i] <= xs[i-1];
            p[0] <= 8'd4 * xs[0];
            p[1] <= 8'd4 * xs[1] + p[0];
            p[2] <= 8'd4 * xs[2] + p[1];
            p[3] <= 8'd4 * xs[3] + p[2];
            p[4] <= 8'd4 * xs[4] + p[3];
            p[5] <= 8'd4 * xs[5] + p[4];
            p[6] <= 8'd4 * xs[6] + p[5];
            p[7] <= 8'd4 * xs[7] + p[6];
            p[8] <= 8'd4 * xs[8] + p[7];
            p[9] <= 8'd4 * xs[9] + p[8];
            p[10] <= 8'd4 * xs[10] + p[9];
            p[11] <= 8'd4 * xs[11] + p[10];
            p[12] <= 8'd4 * xs[12] + p[11];
            p[13] <= 8'd4 * xs[13] + p[12];
            p[14] <= 8'd4 * xs[14] + p[13];
            p[15] <= 8'd4 * xs[15] + p[14];
            p[16] <= 8'd4 * xs[16] + p[15];
            p[17] <= 8'd4 * xs[17] + p[16];
            p[18] <= 8'd4 * xs[18] + p[17];
            p[19] <= 8'd4 * xs[19] + p[18];
            y <= p[19];
        end
    end
endmodule
